INSERT INTO `templates` (`id`, `title`, `description`, `sections`, `is_active`, `created_by`, `created_by_name`, `created_at`, `updated_at`, `standard_key`) VALUES ('115b2ccb-f1f9-4e06-8eb4-8c7177f68a34','Audit logistique et commercial — Dépôt','Trame standard pour les audits dépôt : inventaire stock, clôture de caisse, facturation/livraison, retours clients, organisation et recouvrement. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"eea72ad5-67a6-4a54-ab7c-f1f225c0af09\",\"label\":\"Inventaire stock dépôt\",\"questions\":[{\"id\":\"c751160e-5bc7-4cf7-b99f-6028895165ff\",\"text\":\"Le stock physique correspond-il au stock système (PROXIM/PROMOFOOD/BEESKY) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"e163ea6b-5819-4057-bf31-946b60055411\",\"text\":\"Précisez la nature et la valeur de l\'écart constaté (article, quantité, montant)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"c751160e-5bc7-4cf7-b99f-6028895165ff\",\"triggerValues\":[\"no\"]}},{\"id\":\"4ba775bd-6696-4b5b-8f13-996e51e6f8ad\",\"text\":\"Des articles endommagés ou périmés ont-ils été identifiés ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"95639d2f-273e-439b-8196-da0913ee89fe\",\"text\":\"Détail des articles concernés et prix de liquidation proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"4ba775bd-6696-4b5b-8f13-996e51e6f8ad\",\"triggerValues\":[\"yes\"]}},{\"id\":\"42b0fa40-80e9-4cb2-9655-4a20996f9af7\",\"text\":\"Les mouvements de stock (transferts entre dépôts, gestes commerciaux) sont-ils tracés formellement ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"9464a7c6-8e35-4721-a3b4-5b0038099037\",\"text\":\"Précisez les manques de traçabilité constatés\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"42b0fa40-80e9-4cb2-9655-4a20996f9af7\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"8bec710e-7299-4f81-b835-0d30c0b8251e\",\"label\":\"Clôture de caisse et inventaire véhicule (agents commerciaux)\",\"questions\":[{\"id\":\"08856eed-9224-4b7b-b616-cb1bdc8a9fd4\",\"text\":\"Un écart a-t-il été constaté entre le système (NOMADIS) et les espèces encaissées ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"565f72e9-0cd2-4aa8-9758-5f5847de9e34\",\"text\":\"Montant de l\'écart constaté (DT)\",\"type\":\"NUMBER\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"08856eed-9224-4b7b-b616-cb1bdc8a9fd4\",\"triggerValues\":[\"yes\"]}},{\"id\":\"9ec6be41-5a01-4e86-94f2-48fff1115d8b\",\"text\":\"Un justificatif a-t-il été présenté par l\'agent ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"08856eed-9224-4b7b-b616-cb1bdc8a9fd4\",\"triggerValues\":[\"yes\"]}},{\"id\":\"96892a0c-bb6a-4e41-a3c8-ea4c4c21fbc5\",\"text\":\"L\'écart a-t-il été régularisé immédiatement ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"08856eed-9224-4b7b-b616-cb1bdc8a9fd4\",\"triggerValues\":[\"yes\"]}},{\"id\":\"1a5c4899-7c56-4878-ae15-e0ceba09ecaa\",\"text\":\"Un écart a-t-il été constaté lors de l\'inventaire du stock véhicule ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"afaf9fa0-d74f-4e88-8c76-6b8980192b4b\",\"text\":\"Montant/quantité de l\'écart et régularisation effectuée\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"1a5c4899-7c56-4878-ae15-e0ceba09ecaa\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"e728cd59-ec10-4ee7-817b-13754c23240d\",\"label\":\"Facturation, livraison et retours clients\",\"questions\":[{\"id\":\"a181b093-9eb3-4611-96a4-367e12f98cdb\",\"text\":\"Les livraisons sont-elles systématiquement facturées avant sortie de marchandise ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"0d9cb66e-3089-49c3-a71a-2f816bb4f8b3\",\"text\":\"Précisez les cas de livraison sans facturation préalable et la régularisation effectuée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a181b093-9eb3-4611-96a4-367e12f98cdb\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"828ee142-4f81-4916-ad31-d904e2ae1d02\",\"text\":\"Les remises accordées sont-elles validées officiellement avant application ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"c3bafdfc-401b-4abc-b7ff-34bdc05ab5a1\",\"text\":\"Les retours clients sont-ils traités selon la procédure (déclaration, validation direction) ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"647ebdc9-af39-4dab-b678-5f6ba7b4b2f6\",\"text\":\"Précisez les retours en attente et l\'origine du blocage\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"c3bafdfc-401b-4abc-b7ff-34bdc05ab5a1\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"7e251ac2-a822-46d5-b3fa-da666f37112c\",\"label\":\"Organisation et ressources humaines\",\"questions\":[{\"id\":\"0dd420f4-eb90-48cf-b6cb-7b85c56dfee9\",\"text\":\"Les effectifs administratifs sont-ils suffisants pour les tâches du dépôt ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"7c2c6022-c47c-4c63-bbf1-e8d13cd5cc3f\",\"text\":\"Précisez les tâches impactées et les recommandations (recrutement, réorganisation…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"0dd420f4-eb90-48cf-b6cb-7b85c56dfee9\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"10cf986b-d311-4364-a6f8-339ed79ab363\",\"text\":\"Un organigramme clair et une répartition des tâches sont-ils en place ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true}]},{\"id\":\"11cd11f3-5b56-4feb-8e4c-b828c9d07acf\",\"label\":\"Suivi balance client, recouvrement et effets\",\"questions\":[{\"id\":\"568fe5b6-405f-4728-bb4b-ba37ade10b5f\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"8e4bcb8d-31a3-4943-a719-60f996b50626\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"aab6ba50-45dc-426c-8b9c-eb71f5cc91a3\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"568fe5b6-405f-4728-bb4b-ba37ade10b5f\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"3436dad8-3e7c-49d9-9251-4d0ecdf1c5a0\",\"text\":\"La gestion des effets (traites, échéances) est-elle rigoureuse et à jour ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T13:11:06.140Z','2026-10-21T13:11:06.140Z','depot'),
('1fb022c8-d1e2-4140-92b1-84fe86761d6d','Audit industriel — Usine S2I','Trame standard pour les audits usine : ventes, ordres de fabrication, machines/moules, matières premières, rebuts, recouvrement, RH et sécurité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"e0150c57-c3cb-420f-898c-22f18747dc88\",\"label\":\"Ventes et chiffre d\'affaires\",\"questions\":[{\"id\":\"12e01475-16f5-42b8-ae83-a8ff34796a5e\",\"text\":\"L\'évolution du chiffre d\'affaires du mois est-elle conforme aux objectifs ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"f54c936d-3a63-4e56-9239-0bdccf900176\",\"text\":\"Précisez les écarts constatés et leurs causes (perte de clients, nouveaux clients…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"12e01475-16f5-42b8-ae83-a8ff34796a5e\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"7b3276cd-2531-43f5-9c5e-b7bbbeb7c920\",\"text\":\"Des clients majeurs ont-ils réduit ou arrêté leurs commandes ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"03593ff3-d10c-4fc8-9b55-00c1b3ebbf48\",\"text\":\"Précisez les clients concernés et le plan d\'action commercial\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"7b3276cd-2531-43f5-9c5e-b7bbbeb7c920\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"7398f8c2-5a60-4ceb-9bd3-d73d1c1894ac\",\"label\":\"Ordres de fabrication et sorties matière\",\"questions\":[{\"id\":\"136b9ddd-0c15-420e-85aa-aba73bdcd01b\",\"text\":\"Les ordres de fabrication et bons de sortie matière première sont-ils tous enregistrés et cohérents ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"2de320c2-5acb-422b-8e11-3d4983a15a6f\",\"text\":\"Précisez les écarts ou retards de saisie constatés et la cause (absence, surcharge…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"136b9ddd-0c15-420e-85aa-aba73bdcd01b\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"a066615b-39bc-4035-93bc-43c7c59dcb4f\",\"label\":\"État des machines et moules\",\"questions\":[{\"id\":\"a8a183be-2543-46e8-8ce7-7369f40c1062\",\"text\":\"Les machines et moules sont-ils en bon état de fonctionnement ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"2f120564-23ef-498b-8e67-dfecd99d7bd7\",\"text\":\"Détail des pannes constatées (machine, pièce, durée) et plan d\'action\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a8a183be-2543-46e8-8ce7-7369f40c1062\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"1ae37ef7-1143-4982-a929-8a0a0e2445b3\",\"text\":\"Nombre de machines à l\'arrêt lors de la visite\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false}]},{\"id\":\"aa4dfd54-43db-4b88-a22e-a76c07cda802\",\"label\":\"Inventaire matières premières\",\"questions\":[{\"id\":\"a49d5156-e4ba-4091-8d57-724b26304a1c\",\"text\":\"Le stock physique de matières premières correspond-il aux données système ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"f863c44b-c6f0-46a8-bb44-44ae073fcc4d\",\"text\":\"Précisez les articles et quantités en écart\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a49d5156-e4ba-4091-8d57-724b26304a1c\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"f02531e4-5a80-4b61-96a7-a01d13e56eb0\",\"label\":\"Rebuts et déchets\",\"questions\":[{\"id\":\"19eef61d-3c56-412b-927a-3790b4cf11ba\",\"text\":\"Le taux de rebuts constaté est-il dans la norme attendue ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"1d4c3f1f-eed5-4835-a703-f643332112e1\",\"text\":\"Taux de rebuts constaté (%)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"19eef61d-3c56-412b-927a-3790b4cf11ba\",\"triggerValues\":[\"no\"]}},{\"id\":\"3cb64db2-0ab9-47ca-8cda-d5ace394c511\",\"text\":\"Le stock de déchets à vendre est-il suivi et écoulé régulièrement ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]},{\"id\":\"4dbf2ec2-b08b-46d1-a1b6-af3484de1d54\",\"label\":\"Suivi balance client et recouvrement\",\"questions\":[{\"id\":\"303ed61e-0c08-4829-855a-cb04349188a3\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"fbf4a802-6d82-4e5b-b96e-a55fd4bfdc60\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"a3459447-0b89-4eb3-943f-80ec546db54f\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"303ed61e-0c08-4829-855a-cb04349188a3\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"692f74f0-1fe8-4918-b14c-7af2b095d09e\",\"label\":\"Organisation et climat social\",\"questions\":[{\"id\":\"3e3706b1-ac20-4719-93c7-95967060fb75\",\"text\":\"Les effectifs (production, administratif) sont-ils suffisants ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"2ebb2e06-5db5-4221-bad2-45f3d8faaf52\",\"text\":\"Précisez les postes en tension et les recommandations\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"3e3706b1-ac20-4719-93c7-95967060fb75\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"170b38ab-ad84-4f80-8067-3ceb437d78f4\",\"text\":\"Un conflit ou climat social tendu a-t-il été observé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"b7f00835-e075-47a3-86b8-478504a6a5ba\",\"text\":\"Détail du conflit constaté et mesures recommandées\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"170b38ab-ad84-4f80-8067-3ceb437d78f4\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"dd6dc58c-d867-4f5f-bec3-dd66b8f5c278\",\"label\":\"Hygiène, sécurité et environnement usine\",\"questions\":[{\"id\":\"0968fe15-8561-4e0a-9cce-e655f8b09618\",\"text\":\"L\'état de propreté de l\'usine est-il satisfaisant ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true},{\"id\":\"fe08a77d-d6d6-4d16-a25f-d8fbbcf9cc83\",\"text\":\"Les équipements de sécurité (extincteurs, caméras) sont-ils opérationnels et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"48945c86-e802-452a-869c-ed253cdf7013\",\"text\":\"Précisez les anomalies constatées et les actions correctives\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"fe08a77d-d6d6-4d16-a25f-d8fbbcf9cc83\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"7d956fb2-9776-42aa-9987-ab910d1215d9\",\"text\":\"Le matériel informatique (postes, imprimantes) est-il suffisant et fonctionnel ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T13:11:06.136Z','2026-10-21T13:11:06.136Z','usine'),
('bf602a07-d719-4ba9-8411-a8df277e8dd5','Audit logistique — Déchargement de containers importés','Grille de contrôle standard pour le déchargement des containers importés : contrôle documentaire avant ouverture, inspection de l\'état général, comptage contradictoire et DLC, procédure en cas de non-conformité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"3c7c1466-4955-4905-ae3f-86e88c595e1a\",\"label\":\"Contrôle documentaire (avant ouverture)\",\"questions\":[{\"id\":\"3857cec5-7421-4037-8134-b715c39853ae\",\"text\":\"Le Bill of Lading est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"16155b72-5eef-4915-8cc6-beb6fe9d267d\",\"text\":\"Précisez l\'anomalie constatée sur le Bill of Lading\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"3857cec5-7421-4037-8134-b715c39853ae\",\"triggerValues\":[\"no\"]}},{\"id\":\"83309e31-19dd-4f89-ae38-aa54ba1f593c\",\"text\":\"Le certificat sanitaire est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"ed19d6e4-419d-499c-b9a1-fe94adc2eefd\",\"text\":\"Précisez l\'anomalie constatée sur le certificat sanitaire\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"83309e31-19dd-4f89-ae38-aa54ba1f593c\",\"triggerValues\":[\"no\"]}},{\"id\":\"dcdce4bc-7629-48f0-ae1e-2e2227e31dfb\",\"text\":\"Le certificat d\'origine est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"5bef907f-d987-4ba0-aaea-4d83f2e15d8c\",\"text\":\"Précisez l\'anomalie constatée sur le certificat d\'origine\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"dcdce4bc-7629-48f0-ae1e-2e2227e31dfb\",\"triggerValues\":[\"no\"]}},{\"id\":\"aadd49c0-22d6-4b86-9524-1473caf7fda1\",\"text\":\"Le Packing List est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"269edbc3-716a-4594-b119-4596d56e5943\",\"text\":\"Précisez l\'anomalie constatée sur le Packing List\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"aadd49c0-22d6-4b86-9524-1473caf7fda1\",\"triggerValues\":[\"no\"]}},{\"id\":\"2956a860-47bb-4559-921c-5cb2d485df96\",\"text\":\"Autres documents contrôlés (facture, etc.) — précisez lesquels et leur conformité\",\"type\":\"TEXT\",\"weight\":1,\"required\":false},{\"id\":\"03369111-8d4e-4988-bb37-86c5ee5ab631\",\"text\":\"Existe-t-il un plombage identifiable et numéroté ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"dcc8b823-dd9f-44ef-9e22-c392e4b30f32\",\"text\":\"Précisez l\'anomalie constatée (absence de plombage, numéro illisible…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"03369111-8d4e-4988-bb37-86c5ee5ab631\",\"triggerValues\":[\"no\"]}},{\"id\":\"66334e1c-a75b-4b3a-bb49-eb37368f7a9b\",\"text\":\"Numéro du plombage relevé\",\"type\":\"TEXT\",\"weight\":1,\"required\":false}]},{\"id\":\"0481c24a-5996-4527-b9e2-3b1c1736a16f\",\"label\":\"Inspection de l\'état général du container\",\"questions\":[{\"id\":\"50572675-ab9a-4ab1-96eb-1d67b2e8d4a9\",\"text\":\"Le container est-il intact (absence d\'ouvertures ou de fuites) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"f13dbe30-9969-491a-9db2-4b8ec39c7695\",\"text\":\"Précisez l\'ouverture ou la fuite constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"50572675-ab9a-4ab1-96eb-1d67b2e8d4a9\",\"triggerValues\":[\"no\"]}},{\"id\":\"0ffcd183-7bf4-4183-9bb1-1332f999bc90\",\"text\":\"L\'ouverture des portes du container ne révèle-t-elle aucune anomalie ou suspicion ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"315e7b49-974c-4e3e-8f2f-35caa5f35ed0\",\"text\":\"Précisez l\'anomalie ou la suspicion constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"0ffcd183-7bf4-4183-9bb1-1332f999bc90\",\"triggerValues\":[\"no\"]}},{\"id\":\"79de1a49-ef93-4181-bc12-0f5ceaf70466\",\"text\":\"Le contrôle visuel initial confirme-t-il qu\'aucun carton ou sac n\'est ouvert ou endommagé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"3b0fb481-205a-40cf-b717-e7bdc5bba6c2\",\"text\":\"Précisez les cartons/sacs ouverts ou endommagés constatés\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"79de1a49-ef93-4181-bc12-0f5ceaf70466\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"16534d42-eeda-4527-9449-4f919e76dadc\",\"label\":\"Opérations de déchargement et traçabilité\",\"questions\":[{\"id\":\"0b76490c-213b-4e15-97e0-0cae67baadb4\",\"text\":\"Le comptage contradictoire correspond-il au Packing List (et aux autres documents : facture, Bill of Lading) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"d877104d-5f02-4ed8-8ded-f21cc5f6ec7e\",\"text\":\"Précisez l\'écart constaté (référence, quantité)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"0b76490c-213b-4e15-97e0-0cae67baadb4\",\"triggerValues\":[\"no\"]}},{\"id\":\"5865b815-b43e-4041-80bb-9f320a54c3df\",\"text\":\"Écart de quantité constaté (unités)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false,\"dependsOn\":{\"questionId\":\"0b76490c-213b-4e15-97e0-0cae67baadb4\",\"triggerValues\":[\"no\"]}},{\"id\":\"216039a8-e099-484d-bd6e-c8cce2e4770e\",\"text\":\"Le contrôle des DLC par échantillonnage est-il conforme ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"0598d0e5-2ad1-40d9-8675-34bca9e88d16\",\"text\":\"Précisez les références et DLC non conformes constatées\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"216039a8-e099-484d-bd6e-c8cce2e4770e\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"dd4c54db-a1de-4274-a16f-9eb7e4f0a16f\",\"label\":\"Procédure en cas de non-conformité\",\"questions\":[{\"id\":\"21ad37b8-8f2e-4733-bac8-fc531f0e9281\",\"text\":\"Une non-conformité a-t-elle été détectée durant cet audit ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"e7666c41-dcd8-4d58-a10b-24fd5d18b8a3\",\"text\":\"Description de la non-conformité constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"21ad37b8-8f2e-4733-bac8-fc531f0e9281\",\"triggerValues\":[\"yes\"]}},{\"id\":\"08d96afa-bc86-4c50-ae2e-cc447eeb75b2\",\"text\":\"Des photographies horodatées ont-elles été prises (scellé cassé, marchandise endommagée, container peu rempli…) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"21ad37b8-8f2e-4733-bac8-fc531f0e9281\",\"triggerValues\":[\"yes\"]}},{\"id\":\"89cb5b93-a185-4a48-b44c-f285d9a3ae31\",\"text\":\"Le lot a-t-il été bloqué en zone de quarantaine (non-conformité majeure) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"21ad37b8-8f2e-4733-bac8-fc531f0e9281\",\"triggerValues\":[\"yes\"]}},{\"id\":\"f38f4618-bd8a-4477-a0b0-4aedd8839633\",\"text\":\"Une fiche de non-conformité a-t-elle été émise et transmise à la Direction des Achats ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true,\"dependsOn\":{\"questionId\":\"21ad37b8-8f2e-4733-bac8-fc531f0e9281\",\"triggerValues\":[\"yes\"]}}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T13:11:06.144Z','2026-10-21T13:11:06.144Z','container');
